import { openBank } from './voicebank.js';

// Who reads a phone message aloud, and what they say. phonefeed.js voices
// every notification card in the sender's voice from the sms manifest
// (audio/voicelines/sms, "<speaker>|<text>", falling back to the lines
// manifest), generated by scripts/tts_lines*.{mjs,py}. No browser imports:
// scripts/voicelines_collect.mjs reads the same tables.
//
// A text with numbers or names in it ("+€45", a wijk, a streak) is not read
// literally: the caller passes `say`, a fixed line from SMS_SAY, and the card
// keeps the full text. A text without a recording only gets the ping.

// sender shown on the card -> the voice that reads it
const VOICE_OF = {
  Kiekdoar: 'Kiekdoar-redactie',
  GDE: 'Ubbo',
  Ubbo: 'Ubbo',
  Bank: 'Ubbo',
  'Fjord Frituur': 'Ubbo',
  'Gerrit Krolbrug': 'Verkeersinformatie',
  'Onbekend nummer (058)': 'Mem Terpstra',
  'Henk (Garage Knalpot)': 'Henk',
};

const SMS_NEWS = 'Kiekdoar-redactie';
const SMS_SYSTEM = 'Ubbo';

export function smsSpeaker(from) {
  const f = String(from || 'Kiekdoar').trim();
  if (VOICE_OF[f]) return VOICE_OF[f];
  const base = f.replace(/\s*·.*$/, '').replace(/\s*\(.*\)$/, '').trim();
  return VOICE_OF[base] || base;
}

// The text as it is spoken: without the "KIEKDOAR:" app prefix and without a
// trailing amount ("(+€45)").
export function smsSpoken(text) {
  return String(text || '').trim().replace(/^KIEKDOAR( MELDT)?:\s*/i, '').replace(/\s*\(\+?€\s?[\d.,]+\)$/, '').trim();
}

// Fixed voiced lines for texts with a variable part. { speaker, lines }.
export const SMS_SAY = {
  // story.js: the step reminder names the step title
  remindT: { speaker: 'Tammo', lines: ['Nog even dit. Het staat op je kaart, als je zin hebt.'] },
  remindA: { speaker: 'Anita', lines: ['Nog even dit. Het staat op je kaart, als je zin hebt.'] },
  // missions.js: a mission needs something first (a shop name in the text)
  gate: { speaker: SMS_SYSTEM, lines: ['Voor deze missie mis je nog iets. Lees even mee op je telefoon.'] },
  // postgame.js: the Fjord Frituur's day takings
  fjordPay: { speaker: SMS_SYSTEM, lines: ['Goeiemorgen! Gisteren lekker gedraaid. De dagomzet staat op je rekening.'] },
  // flavourlines.js PEERD_NEWS, same order, without the wijk
  peerd: { speaker: SMS_NEWS, lines: [
    'Peerd van Ome Loeks gezien op een rotonde. Gemeente: “Het beeld staat gewoon op zijn plek.”',
    'Weer meldingen van het Peerd op een rotonde. Gemeente: “Wij verplaatsen geen paarden.”',
    'Het Peerd van Ome Loeks staat ergens anders, zeggen bewoners. Gemeente: “Dat moet een ander paard zijn.”',
    'Rotonde heeft ineens een paard. Gemeente ontkent alles, ook het paard.',
  ] },
  // flavourlines.js BIKE_RESURFACE, same order, without the places
  bike: { speaker: SMS_NEWS, lines: [
    'Die gejatte fiets staat nu ergens anders. Met een ander slot.',
    'Gevonden: een fiets die gisteren nog ergens anders stond. Niemand weet van niks.',
    'Gejatte fiets duikt op aan de andere kant van de stad. Het zadel is nog warm.',
  ] },
  // sidejob_<id>.js sikkom(c): the streak without its number
  job_bezorger: { speaker: SMS_NEWS, lines: ['Bezorger fietst bestelling na bestelling warm door de stad, klanten verbijsterd.'] },
  job_bus: { speaker: SMS_NEWS, lines: ['Buslijn 3 rijdt alweer volgens de dienstregeling, reizigers in verwarring.'] },
  job_taxi: { speaker: SMS_NEWS, lines: ['Taxichauffeur rijdt klant na klant keurig naar huis. Centrale denkt aan een storing.'] },
  job_fietsdepot: { speaker: SMS_NEWS, lines: ['Handhaver ruimt het Stationsplein keer op keer leeg, fietsenrekken voor het eerst ooit halfvol.'] },
  job_rondvaart: { speaker: SMS_NEWS, lines: ['Rondvaartgids vaart tocht na tocht zonder één toerist overboord.'] },
  job_verhuizing: { speaker: SMS_NEWS, lines: ['Verhuizer zet student na student heel op hun nieuwe kamer, kamernood officieel een beetje minder.'] },
};

// attention.js kind of a voiced text: a character's message always, the
// news feed and the app texts sparingly
export const smsKind = (speaker) => (speaker === SMS_NEWS ? 'news' : speaker === SMS_SYSTEM ? 'system' : 'story');

const smsBank = openBank('sms');
const hintBank = openBank('hints');

// HUD cards phrased as someone talking (mission stage lines, hints, side-job
// instructions; hudcards.js) are said by the companion from the hints
// manifest, keyed by the card text without a trailing counter ("(3x)",
// "(+12s)", "(2/5)"); a card with a variable part passes `say`.
export const cardSpoken = (text) => String(text || '').trim().replace(/\s*\([^()]*\d[^()]*\)$/, '').trim();

export function hintVoiceFor(speaker, text) {
  return hintBank.lookup(speaker, text);
}

// { speaker, text, src, dur } of the recording for this card, or null.
// lineVoice: linevoice.js lineVoiceFor (the lines manifest fallback).
export function smsVoiceFor(n, lineVoice = null) {
  const speaker = smsSpeaker(n.from || (/^KIEKDOAR/i.test(n.text || '') ? 'Kiekdoar' : n.from));
  const text = n.say || smsSpoken(n.text);
  if (!text) return null;
  const v = smsBank.lookup(speaker, text);
  if (v) return { speaker, text, src: v.src, dur: v.dur };
  const l = lineVoice && lineVoice(speaker, text);
  return l ? { speaker, text, src: l.src, dur: l.dur } : null;
}
